$record=old_form($record ?? ['subject_name'=>'','teacher_id'=>'','branch_id'=>'','room'=>'','day_of_week'=>1,'period_start'=>1,'period_end'=>3]);
$branches=rows('SELECT id,branch_name FROM branches ORDER BY branch_name');
$teachers=rows('SELECT id,full_name,expertise FROM teachers ORDER BY full_name');
?>
